arguments.command:
python3 << 'EOF'
# Read the combined shard
with open('/tmp/combined_shard', 'rb') as f:
    data = f.read()

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

primes = [i for i in range(2, len(data) + 1000) if is_prime(i)]

# Try XOR with ASCII characters starting from 66, using prime values as offsets
result = bytearray()
for i, byte in enumerate(data):
    if i < len(primes):
        xor_val = (66 + primes[i]) % 256
        result.append(byte ^ xor_val)
    else:
        result.append(byte)

print("Decoded with (66 + prime) as XOR values:")
print(result[:300])
print("\n\nAs text:")
try:
    print(result[:300].decode('utf-8', errors='replace'))
except:
    print("Not valid UTF-8")
EOF

